(()=>{const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('#nav');menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open)});nav?.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{menu.setAttribute('aria-expanded','false');nav.classList.remove('open')}));document.querySelectorAll('[data-work-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-work-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});document.querySelectorAll('.new-project').forEach(card=>card.hidden=b.dataset.workFilter!=='all'&&card.dataset.category!==b.dataset.workFilter)}));document.querySelectorAll('[data-media-id]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-media-id]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});const frame=document.getElementById('green-tv-player');frame.src='https://www.youtube-nocookie.com/embed/'+b.dataset.mediaId+'?autoplay=1';frame.title=b.textContent.trim();document.getElementById('green-tv-external').href='https://youtu.be/'+b.dataset.mediaId}));if(document.querySelector('#year'))document.querySelector('#year').textContent=new Date().getFullYear();const redirects={'#product-launches':'products.html#product-launches','#care-product-launches':'products.html#care-product-launches','#website-launches':'digital.html#website-launches','#campaign-videos':'campaigns.html#campaign-videos','#career-timeline':'about.html#career-timeline','#about':'about.html','#contact':'contact.html'};if(/\/$|\/index.html$/.test(location.pathname)&&redirects[location.hash])location.replace(redirects[location.hash]);})();
